// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// app (.open-next/worker.js, written by `opennextjs-cloudflare build`), wrapped
// so every response carries the security headers and a per-request CSP nonce,
// plus the voice socket (worker/voice.ts), the daily model check (the
// scheduled handler, agent/model-check.ts) and the Durable Object classes the
// app uses.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file exists only after a build
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import openNext from '../.open-next/worker.js'
import { canonicalRedirect } from '../lib/security/canonical'
import { buildContentSecurityPolicy, createNonce, staticSecurityHeaders } from '../lib/security/headers'
import { healthCheck } from './health'
import { VOICE_PATH, handleVoice } from './voice'
import { runModelCheck } from '../agent/model-check'

export { WrenAgent } from '../agent/wren-agent'
export { DailyCounter } from '../agent/daily-counter'
export { ModelCheck } from '../agent/model-check-store'

interface OpenNextHandler {
  fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response>
}

export default {
  async fetch(request, env, ctx): Promise<Response> {
    // The uptime check (GET /healthz) answers before the redirect, Next.js, auth or the database.
    const health = healthCheck(request)
    if (health) return health

    const url = new URL(request.url)
    const https = url.protocol === 'https:'

    // The workers.dev address forwards to Wren's own (lib/security/canonical.ts).
    const canonical = canonicalRedirect(request.url, env.PUBLIC_URL)
    if (canonical) {
      const moved = new Response(null, { status: 308, headers: { Location: canonical } })
      for (const [name, value] of staticSecurityHeaders({ https })) moved.headers.set(name, value)
      return moved
    }
    const csp = buildContentSecurityPolicy({ nonce: createNonce(), https })

    // The voice socket goes straight to the person's agent (worker/voice.ts).
    const response =
      url.pathname === VOICE_PATH ? await handleVoice(request, env) : await openNextResponse(request, env, ctx, csp)

    // A WebSocket upgrade's response can't be copied.
    if (response.status === 101) return response
    const secured = new Response(response.body, response)
    secured.headers.set('Content-Security-Policy', csp)
    for (const [name, value] of staticSecurityHeaders({ https })) secured.headers.set(name, value)
    return secured
  },

  // The daily model check (the cron in wrangler.jsonc). Only a Cron Trigger
  // reaches this; `wrangler dev --test-scheduled` adds /__scheduled locally.
  async scheduled(_controller, env): Promise<void> {
    await runModelCheck(env)
  },
} satisfies ExportedHandler<CloudflareEnv>

function openNextResponse(request: Request, env: CloudflareEnv, ctx: ExecutionContext, csp: string): Promise<Response> {
  // Next reads the nonce from the request's CSP header and adds it to every
  // script it renders. Any CSP header a client sent is replaced.
  const headers = new Headers(request.headers)
  headers.set('Content-Security-Policy', csp)
  // cf (the visitor's country, lib/server/region.ts) is passed on explicitly,
  // and so is the signal (it isn't copied to a new Request): OpenNext ends the
  // response when it fires, so a visitor leaving cancels a streamed answer or
  // run watch instead of OpenNext writing into the closed stream ("Unable to
  // enqueue") while the answer runs on.
  return (openNext as OpenNextHandler).fetch(new Request(request, { headers, cf: request.cf, signal: request.signal }), env, ctx)
}
